// Interface languages. The French text is the key: `t("Profil créé")`,
// `t("Profil « {name} » importé", { name })`. A missing entry falls back to
// French. Static text of index.html is translated once at start-up by
// translateDom (text nodes, title / placeholder attributes, and elements
// marked data-i18n-html whose whole inner HTML is one entry).
"use strict";

const LANGS = ["fr", "en", "de", "it", "es"];
let LANG = "fr";

// The system G Nexus runs on, from the web view (WebKitGTK on Linux, WebView2 on
// Windows); `?os=linux` in a plain browser (dev-mock). Elements marked `win-only` /
// `linux-only` are shown on that system only (style.css).
const OS = new URLSearchParams(location.search).get("os") || (/Linux/.test(navigator.userAgent) ? "linux" : "windows");
const ON_LINUX = OS === "linux";
document.documentElement.classList.add(`os-${OS}`);

