/** Translate `key` (French) into the current language and fill `{vars}`. */
function t(key, vars) {
  const i = LANGS.indexOf(LANG) - 1;
  let s = (i >= 0 && TR[key] && TR[key][i]) || key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
  return s;
}

/** Language to use: the saved choice, else the system's, else French. */
function pickLang(saved) {
  if (LANGS.includes(saved)) return saved;
  const sys = (navigator.language || "fr").slice(0, 2).toLowerCase();
  return LANGS.includes(sys) ? sys : "fr";
}

const norm = (s) => s.replace(/\s+/g, " ").trim();

/** Translate the static page once (call before any data is rendered). */
function translateDom(root = document.body) {
  document.documentElement.lang = LANG;
  if (LANG === "fr") return;
  for (const el of root.querySelectorAll("[data-i18n-html]")) {
    const key = norm(el.innerHTML);
    if (TR[key]) el.innerHTML = t(key);
  }
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let n = walker.nextNode(); n; n = walker.nextNode()) {
    if (n.parentElement.closest("script, style, [data-i18n-html]")) continue;
    const key = norm(n.nodeValue);
    if (key && TR[key]) n.nodeValue = n.nodeValue.replace(n.nodeValue.trim(), t(key));
  }
  for (const el of root.querySelectorAll("[title], [placeholder]")) {
    for (const a of ["title", "placeholder"]) {
      const v = el.getAttribute(a);
      if (v && TR[norm(v)]) el.setAttribute(a, t(norm(v)));
    }
  }
}
